<?php
session_start();require 'config/database.php';require 'lib_results.php';require 'lib_phase8.php';
if(!isset($_SESSION['user'])||$_SESSION['user']['role']!=='student'){header('Location: login.php');exit;}
$q=$pdo->prepare('SELECT st.*,u.name,u.email,p.level,p.name program_name,p.specialization FROM students st JOIN users u ON u.id=st.user_id JOIN programs p ON p.id=st.program_id WHERE st.user_id=?');$q->execute([$_SESSION['user']['id']]);$student=$q->fetch();if(!$student)exit('Student profile not found.');
$terms=studentTerms($pdo,(int)$student['id']);$history=[];foreach($terms as $term){$status=resultStatus($pdo,(int)$student['id'],$term);if(in_array($status,['published','locked'],true)){$r=studentResult($pdo,(int)$student['id'],$term);$history[]=['term'=>$term,'status'=>$status,'gpa'=>$r['gpa'],'credits'=>$r['credits'],'quality'=>$r['quality'],'rows'=>$r['rows']];}}
$overall=studentOverall($pdo,(int)$student['id']);
$pageTitle='Transcript';require'includes/header.php';?><div class="container py-4"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2 class="fw-bold">Academic Transcript</h2><p class="text-muted mb-0"><?=htmlspecialchars($student['name'].' · '.$student['roll_no'].' · '.$student['program_name'])?></p></div><div class="d-flex gap-2"><button class="btn btn-primary" onclick="window.print()">Print Transcript</button><a href="student.php" class="btn btn-outline-secondary">Back</a></div></div>
<div class="card shadow-sm border-0"><div class="card-body"><div class="row g-3 mb-4"><div class="col-md-4"><small class="text-muted">Program</small><h5><?=htmlspecialchars($student['program_name'])?></h5></div><div class="col-md-4"><small class="text-muted">Overall GPA</small><h3><?=number_format($overall['gpa'],2)?></h3></div><div class="col-md-4"><small class="text-muted">Published Terms</small><h3><?=count($history)?></h3></div></div>
<?php foreach($history as $h):?><div class="border rounded p-3 mb-4"><div class="d-flex justify-content-between"><div><h5 class="mb-1"><?=htmlspecialchars($h['term'])?></h5><span class="badge text-bg-success"><?=htmlspecialchars(strtoupper($h['status']))?></span></div><div class="text-end"><strong>GPA <?=number_format($h['gpa'],2)?></strong><br><small><?=$h['credits']?> credit hours</small></div></div><div class="table-responsive mt-3"><table class="table table-sm"><thead><tr><th>Code</th><th>Subject</th><th>CH</th><th>%</th><th>Grade</th><th>GP</th></tr></thead><tbody><?php foreach($h['rows'] as $r):?><tr><td><?=htmlspecialchars($r['code'])?></td><td><?=htmlspecialchars($r['name'])?></td><td><?=number_format($r['credit_hours'],1)?></td><td><?=number_format($r['percent'],2)?>%</td><td><?=htmlspecialchars($r['letter_grade'])?></td><td><?=number_format($r['grade_point'],2)?></td></tr><?php endforeach;?></tbody></table></div></div><?php endforeach;if(!$history):?><div class="alert alert-info">No published academic terms are available yet.</div><?php endif;?></div></div></div><style>@media print{.btn{display:none!important}.card{box-shadow:none!important;border:0!important}}</style><?php require'includes/footer.php';?>